function notice(s,error=false){$('#notice').textContent=s;$('#notice').className=error?'show error':'show';clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#notice').className='',7000)}
async function api(path,body){if(demo)return demo.api(path,body);const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok){const e=Error(d.error);e.status=r.status;throw e}return d}

function addPasswordToggles(root){
 root.querySelectorAll('input[type="password"]').forEach((input,index)=>{
  if(input.parentElement.classList.contains('password-wrap'))return;
  if(!input.id)input.id='secret-field-'+index;
  const wrap=document.createElement('span');wrap.className='password-wrap';
  input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);
  const button=document.createElement('button');button.type='button';button.className='password-toggle';
  button.setAttribute('aria-controls',input.id);button.setAttribute('aria-pressed','false');
  const eye='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>';
  const hiddenEye='<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m3 3 18 18M10.5 5.1 12 5c6.5 0 10 7 10 7a20 20 0 0 1-3.2 4.1M6.1 6.1A22 22 0 0 0 2 12s3.5 7 10 7a12 12 0 0 0 5.1-1.1M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>';
  const label=input.name==='token'?'Kodni':'Parolni';
  button.innerHTML=eye;button.setAttribute('aria-label',label+' ko‘rsatish');button.title=label+' ko‘rsatish';
  button.addEventListener('click',event=>{
   event.preventDefault();
   const show=input.type==='password';input.type=show?'text':'password';
   button.innerHTML=show?hiddenEye:eye;
   button.setAttribute('aria-pressed',String(show));
   button.setAttribute('aria-label',label+(show?' yashirish':' ko‘rsatish'));
   button.title=button.getAttribute('aria-label');
  });
  wrap.appendChild(button);
 });
}

function passwordFields(){return '<label>Yangi parol<input required type="password" name="password" minlength="12" maxlength="128" autocomplete="new-password"></label><small>Kamida 12 belgi: bosh harf, raqam va maxsus belgi.</small><label>Parolni takrorlang<input required type="password" name="confirm" autocomplete="new-password"></label>'}
function auth(mode='login'){state=null;$('#app').innerHTML=`<div class="auth"><section class="authbrand"><div class="seal">◈</div><p class="eyebrow">TOSHKENT 1-SON</p><h1>IIV<br>akademik litseyi</h1><p>Intizom. Bilim. Taraqqiyot.</p><div class="authline"></div><p>O‘quv jarayonining yagona<br>raqamli boshqaruv markazi</p><small>SMART CAMPUS · 2026 / 2027</small></section><section class="authform"><span class="eyebrow">SHAXSIY KABINET</span><h2>${mode==='setup'?'Administratorni faollashtirish':mode==='activate'?'Foydalanuvchi hisobini faollashtirish':'Xush kelibsiz'}</h2><p class="muted">${mode==='setup'?'Bir martalik kod Render xizmatining SETUP_TOKEN sozlamasida.':mode==='activate'?'Administrator bergan taklif kodini kiriting.':'Davom etish uchun hisobingizga kiring.'}</p><form id="authform">${mode!=='login'?'<label>Faollashtirish kodi<input name="token" type="password" required autocomplete="off"></label>':''}${mode!=='activate'?'<label>Elektron pochta<input name="email" type="email" required autocomplete="username"></label>':''}${mode==='login'?'<label>Parol<input name="password" type="password" required autocomplete="current-password"></label>':passwordFields()}<button class="primary" type="submit">${mode==='login'?'Kirish':'Faollashtirish'}</button><p id="formerror" role="alert"></p></form>${mode==='login'?'<button class="textbutton" id="activate">Taklif kodi bilan faollashtirish →</button>':'<button class="textbutton" id="backlogin">Kirish oynasiga qaytish</button>'}<p class="authfoot">Kirish huquqi bosh administrator tomonidan beriladi.</p><section class="demologin"><b>Parolsiz sinab ko‘rish</b><p>Namunaviy ma’lumotlar bilan kabinetni tekshiring.</p><div><a class="secondary" href="/?demo=zavuch">Zavuch kabineti ↗</a><a class="secondary" href="/?demo=teacher">O‘qituvchi kabineti ↗</a></div></section></section></div>`;addPasswordToggles($('#authform'));$('#authform').onsubmit=async e=>{e.preventDefault();if(busy)return;const b=Object.fromEntries(new FormData(e.target));if(mode!=='login'&&b.password!==b.confirm){$('#formerror').textContent='Parollar mos kelmadi';return}busy=true;const button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{await api(mode,b);await load()}catch(e){$('#formerror').textContent=e.message}finally{busy=false;button.disabled=false}};$('#activate')?.addEventListener('click',()=>auth('activate'));$('#backlogin')?.addEventListener('click',()=>auth('login'))}
async function load(){try{const status=await api('status');if(status.setup){auth('setup');return}try{state=await api('me')}catch(e){if(e.status===401){auth();return}throw e}if(state.user.role==='admin'){records=[];programs=[];history=[];members=(await api('members')).members;}else{const roster=await api('assignments');assignments=roster.assignments;teacherAccounts=roster.teachers;records=(await api('records')).records;if(state.permissions.includes('preparation'))programs=(await api('preparation')).programs;else programs=[];if(state.user.role==='zavuch')history=(await api('audit')).audit;}render()}catch(e){$('#app').innerHTML='<div class="loading"><h2>Bog‘lanish amalga oshmadi</h2><p id="loaderror"></p><button id="retry" class="primary">Qayta urinish</button></div>';$('#loaderror').textContent=e.message;$('#retry').onclick=load}}
function icon(k){const paths={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',profile:'M20 21v-2a7 7 0 0 0-14 0v2M13 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',attendance:'M9 4H5v17h14V4h-4M9 2h6v4H9zM8 13l3 3 5-6',grades:'M4 3h16v18H4zM8 3v7l4-2 4 2V3',arrivals:'M12 21s7-6 7-12a7 7 0 0 0-14 0c0 6 7 12 7 12zM12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',monthly:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',teachers:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-2a6 6 0 0 1 12 0v2M16 4a4 4 0 0 1 0 8M18 15a6 6 0 0 1 4 6',staff:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-2a6 6 0 0 1 12 0M16 16l2 2 4-5',students:'M2 8l10-5 10 5-10 5zM6 10v7c4 3 8 3 12 0v-7M22 8v7',graduates:'M2 8l10-5 10 5-10 5zM6 10v7c4 3 8 3 12 0v-7M22 8v7',groups:'M5 3h14v18H5zM2 7h6M2 12h6M2 17h6M11 7h5M11 12h5M11 17h5',rooms:'M4 21V7h9v14M13 12h7v9M7 10h3M7 14h3M7 18h3M16 15h2M16 18h2M2 21h20',schedule:'M4 5h16v16H4zM8 2v6M16 2v6M4 10h16',preparation:'M4 3h13l3 3v15H4zM8 8h8M8 12h8M8 16h5',access:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-2a6 6 0 0 1 12 0M17 10l2 2 3-4',audit:'M12 3a9 9 0 1 0 9 9M12 7v5l4 2M17 3h4v4'};return `<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.preparation}"/></svg>`}
function roleName(){return state.user.role==='admin'?'Texnik administrator':state.user.role==='teacher'?'O‘qituvchi':'O‘quv ishlari bo‘yicha direktor o‘rinbosari'}
function render(){const admin=state.user.role==='admin';const sections=state.user.role==='teacher'?[['ISH MAYDONI',['dashboard','profile','preparation','schedule','attendance','grades','arrivals','monthly']],['JAMOA VA RO‘YXATLAR',['students','groups']],['BOSHQARUV',['accessstatus','announcements','curricula']]]:[['ISH MAYDONI',['dashboard','profile','attendance','grades','arrivals','monthly']],['JAMOA VA RO‘YXATLAR',['teachers','staff','students','graduates','groups','rooms']],['O‘QUV JARAYONI',['schedule','preparation','assignments','curricula']],['BOSHQARUV',['announcements','access','audit']]];const allowed=k=>k==='dashboard'||k==='profile'||(k==='curricula'&&admin)||(k==='access'?admin:k==='audit'?state.user.role==='zavuch':state.permissions.includes(k));const today=new Intl.DateTimeFormat('uz-UZ',{timeZone:'Asia/Tashkent',day:'numeric',month:'long',year:'numeric'}).format(new Date());$('#app').innerHTML=`<div class="shell"><aside><div class="brand"><span class="brandmark">${icon('students')}</span><div>SMART CAMPUS<small>TOSHKENT 1-SON IIV<br>AKADEMIK LITSEYI</small></div></div><nav>${sections.map(([title,keys])=>{const items=keys.filter(allowed);return items.length?`<div class="navlabel">${title}</div>${items.map(k=>`<button data-page="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${icon(k)}<span class="navtext">${labels[k]}</span>${page===k?'<i class="navdot"></i>':''}</button>`).join('')}`:''}).join('')}</nav><div class="systemstate"><span><i></i>Tizim faol</span><small>2026–2027 o‘quv yili</small></div><div class="profile"><span>${admin?'AX':state.user.role==='teacher'?'O‘':'ZV'}</span><div>${esc(state.user.name)}<small>${roleName()}</small></div></div></aside><main><header><span>Toshkent 1-son IIV <b>akademik litseyi</b></span><button id="logout" class="secondary">${demo?'Namoyishdan chiqish':'Chiqish'}</button></header><div class="content">${demo?demoBanner():''}<div class="heading"><div><div class="eyebrow">SMART CAMPUS <span>/ O‘QUV ISHLARI</span></div><h1>${labels[page]}<em>.</em></h1><p class="muted">${page==='dashboard'?(admin?'Hisoblar, kirish ruxsati va xizmatning texnik holati.':'Litsey hayoti va kundalik jarayonlar bir nazorat oynasida.'):page==='access'?'Hisoblar va foydalanish huquqlarini boshqaring.':page==='preparation'?'Namunaviy dasturdan ishchi dastur va taqvim rejagacha.':'Ma’lumotlar va kundalik ishlar uchun yagona ish maydoni.'}</p></div><div class="today">${icon('schedule')} ${today}</div></div><div id="page"></div><footer>SmartCampus · Toshkent 1-son IIV akademik litseyi</footer></div></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#logout').onclick=async()=>{if(demo){location.assign('/');return}try{await api('logout',{});auth()}catch(e){notice(e.message,true)}};if(page==='dashboard'){if(admin)technicalDashboard();else if(state.user.role==='teacher')teacherDashboard();else dashboard();}else if(page==='profile')profilePage();else if(page==='access')access();else if(page==='audit')audit();else if(page==='preparation')preparation();else if(page==='monthly')state.user.role==='teacher'?myMonthlyPage():monthlyPage();else if(page==='assignments')assignmentsPage();else if(page==='curricula')curriculaPage();else if(page==='accessstatus')myAccessPage();else if(page==='schedule'&&state.user.role==='teacher')teacherSchedule();else if(page==='groups'&&state.user.role==='teacher')teacherGroups();else if(page==='arrivals'&&state.user.role==='teacher')myArrivals();else table();bindDemo()}
function profilePage(){if(state.user.role==='teacher'){teacherProfile();return}$('#page').innerHTML=`<section class="panel"><h3>Mening kabinetim</h3><div class="profile-details"><div><small>F.I.Sh.</small><strong>${esc(state.user.name)}</strong></div><div><small>Elektron pochta</small><strong>${esc(state.user.email)}</strong></div><div><small>Lavozim va vakolat</small><strong>${roleName()}</strong></div><div><small>Foydalanish mumkin bo‘lgan bo‘limlar</small><strong>${state.user.role==='admin'?'Hisoblar va texnik holat':state.permissions.map(k=>labels[k]).join(' · ')}</strong></div></div>${state.permissions.includes('preparation')?'<button class="primary" id="profileprep">'+icon('preparation')+' Darsga tayyorgarlik</button>':''}</section>`;$('#profileprep')?.addEventListener('click',()=>go('preparation'))}
function campusArt(){return `<div class="campus-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="building"><div class="building-roof">${icon('students')}</div><div class="building-columns"><i></i><i></i><i></i><i></i></div><div class="building-base"></div></div><div class="campus-badge"><span>✓</span> Smart Campus</div></div>`}
function groupOptions(){return [...new Set(records.filter(r=>r.kind==='groups').map(r=>r.data.name))].sort((a,b)=>a.localeCompare(b))}
function schoolYear(month){const y=Number(month.slice(0,4)),m=Number(month.slice(5));const start=m>=9?y:y-1;return start+'-'+(start+1)}
function filterPanel(){return `<section class="reportfilters"><b>${icon('groups')} Hisobotni saralash</b><label>Hisobot oyi<input id="reportmonth" type="month" value="${esc(dashboardMonth)}"></label><label>O‘quv yili<select id="reportyear">${['2025-2026','2026-2027','2027-2028'].map(y=>`<option ${y===schoolYear(dashboardMonth)?'selected':''}>${y}</option>`).join('')}</select></label><label>Guruh<select id="reportgroup"><option value="">Barcha guruhlar</option>${groupOptions().map(g=>`<option ${g===dashboardGroup?'selected':''}>${esc(g)}</option>`).join('')}</select></label></section>`}
function bindFilters(callback){$('#reportmonth').onchange=e=>{dashboardMonth=e.target.value;callback()};$('#reportgroup').onchange=e=>{dashboardGroup=e.target.value;callback()};$('#reportyear').onchange=e=>{const start=Number(e.target.value.split('-')[0]);const month=Number(dashboardMonth.split('-')[1])||9;dashboardMonth=(month>=9?start:start+1)+'-'+String(month).padStart(2,'0');$('#reportmonth').value=dashboardMonth;callback()}}
function dashboard(){const admin=state.user.role==='admin';const start=state.permissions.includes('groups')?'groups':state.permissions.includes('preparation')?'preparation':state.permissions[0]||'profile';$('#page').innerHTML=`${admin?`<section class="accessstrip"><div class="accessstrip-icon">${icon('access')}</div><div><b>O‘qituvchilar va xodimlarning kirish ruxsati</b><p>Hisoblar, taklif kodlari va foydalanish huquqlarini boshqarish</p></div><button id="dashboardaccess" class="primary">${icon('access')} Foydalanish huquqlari</button></section>`:''}${filterPanel()}<section class="welcome"><div><span class="eyebrow">✧ AKADEMIK LITSEY · YANGI AVLOD PLATFORMASI</span><h2>Assalomu alaykum,<br><strong>${roleName()}!</strong></h2><p>Litsey boshqaruvi, o‘quv jarayoni va jamoa faoliyatini yagona oynada kuzating.</p><button class="light" id="start">${start==='groups'?'Guruhlarni ochish':start==='preparation'?'Darsga tayyorgarlik':'Kabinetni ochish'} ↗</button></div>${campusArt()}</section><div class="stats" id="dashboardstats"></div><div class="grid"><section class="panel"><h3>Tezkor amallar</h3>${[['preparation','Darsga tayyorgarlik','Namunaviy dastur, ishchi dastur va taqvim reja.'],['students','O‘quvchilar ro‘yxati','O‘quvchilar ma’lumotlarini boshqarish.'],['attendance','Dars davomati','Davomat yozuvlarini kiritish va kuzatish.'],['schedule','Dars jadvali','Fanlar, vaqt va xonalarni rejalashtirish.']].filter(([k])=>state.permissions.includes(k)).map(([k,t,d])=>`<button class="step" data-module="${k}"><b>${icon(k)}</b><div><strong>${t}</strong><small>${d}</small></div><span>↗</span></button>`).join('')}</section><section class="panel"><h3>Hisobot ko‘rinishi</h3><div id="dashboardreport" class="reportpreview"></div><div class="note">Саралаш ойлик давомат ҳисоботига қўлланади. Рўйхатлардаги умумий сонлар алоҳида кўрсатилади.</div></section></div>`;$('#start').onclick=()=>go(start);$('#dashboardaccess')?.addEventListener('click',()=>go('access'));document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>go(b.dataset.module));const cards=['teachers','students','groups','preparation'].filter(k=>state.permissions.includes(k));$('#dashboardstats').innerHTML=cards.map(k=>`<button class="stat" data-card="${k}"><span class="stat-icon">${icon(k)}</span><span>${labels[k]}</span><strong>${k==='preparation'?programs.length:records.filter(r=>r.kind===k).length}</strong><small>Jami ro‘yxatda <span>↗</span></small></button>`).join('');document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>go(b.dataset.card));bindFilters(dashboardReport);dashboardReport()}
async function dashboardReport(){const target=$('#dashboardreport');if(!state.permissions.includes('monthly')){target.innerHTML='<p class="muted">O‘z faningiz bo‘yicha hujjatlarni «Darsga tayyorgarlik» bo‘limida tayyorlang.</p>';return}target.innerHTML='<p class="muted">Hisobot yuklanmoqda…</p>';try{const r=await api('monthly?month='+encodeURIComponent(dashboardMonth)+'&group='+encodeURIComponent(dashboardGroup));if(!target.isConnected)return;target.innerHTML=`<div class="reportnumbers"><div><strong>${r.rows.length}</strong><small>O‘quvchi</small></div><div><strong>${r.rows.reduce((s,r)=>s+r.present,0)}</strong><small>Kelgan kunlar</small></div><div><strong>${r.rows.reduce((s,r)=>s+r.absent,0)}</strong><small>Kelmagan kunlar</small></div></div><p class="muted">${esc(dashboardMonth)} · ${esc(dashboardGroup||'Barcha guruhlar')}</p><button class="secondary" id="viewmonthly">Oylik tabelni ochish ↗</button>`;$('#viewmonthly').onclick=()=>go('monthly')}catch(e){target.textContent=e.message}}
async function monthlyPage(){$('#page').innerHTML=filterPanel()+'<section class="panel"><h3>Davomat asosida oylik tabel</h3><p class="muted">Kunlar «Dars davomati»dagi sana va holat bo‘yicha jamlanadi. Bir o‘quvchining bir kundagi bir nechta yozuvida oxirgi kiritilgan holat olinadi.</p><div id="monthlyresult"></div></section>';bindFilters(monthlyResult);await monthlyResult()}
async function monthlyResult(){const el=$('#monthlyresult');el.innerHTML='<p>Yuklanmoqda…</p>';try{const r=await api('monthly?month='+encodeURIComponent(dashboardMonth)+'&group='+encodeURIComponent(dashboardGroup));if(!el.isConnected)return;el.innerHTML=`<div class="tablewrap"><table><thead><tr><th>O‘quvchi</th><th>Guruh</th><th>Keldi</th><th>Kelmadi</th><th>Sababli</th><th>Boshqa holat</th></tr></thead><tbody>${r.rows.map(row=>`<tr><td>${esc(row.name)}</td><td>${esc(row.group)}</td><td>${row.present}</td><td>${row.absent}</td><td>${row.excused}</td><td>${row.other}</td></tr>`).join('')}</tbody></table></div>${!r.rows.length?'<div class="empty">Tanlangan oy va guruh uchun davomat ma’lumoti yo‘q.</div>':''}${r.undated?`<p class="note">${r.undated} ta yozuvda YYYY-MM-DD shaklidagi sana yo‘q. Ular hisobga olinmadi.</p>`:''}<button class="secondary" id="exportmonthly">CSV yuklash</button>`;$('#exportmonthly').onclick=()=>{const csv='\uFEFF'+[['O‘quvchi','Guruh','Keldi','Kelmadi','Sababli','Boshqa'],...r.rows.map(x=>[x.name,x.group,x.present,x.absent,x.excused,x.other])].map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Oylik_tabel_'+dashboardMonth+'.csv';a.click();URL.revokeObjectURL(url)}}catch(e){el.textContent=e.message}}

function go(k){page=k;query='';render()}
function filtered(){return records.filter(r=>r.kind===page&&JSON.stringify(r.data).toLowerCase().includes(query.toLowerCase()))}
function table(){const fs=fields[page],readonly=state.user.role==='teacher'&&!['attendance','grades'].includes(page);$('#page').innerHTML=`<section class="panel"><div class="toolbar"><input class="search" id="search" placeholder="Qidirish…" aria-label="Qidirish" value="${esc(query)}">${!readonly&&state.user.role==='zavuch'?'<button class="secondary" id="import">CSV import</button>':''}<button class="secondary" id="export">CSV yuklash</button>${!readonly?'<button class="primary" id="add">+ Qo‘shish</button>':''}</div><div class="tablewrap"><table><thead><tr><th>№</th>${fs.map(f=>`<th>${f}</th>`).join('')}<th>Amal</th></tr></thead><tbody id="rows"></tbody></table></div><div id="empty"></div><div class="tablefoot" id="rowcount"></div></section>`;$('#search').oninput=e=>{query=e.target.value;paintRows()};$('#add')?.addEventListener('click',()=>recordDialog());$('#export').onclick=exportCSV;$('#import')?.addEventListener('click',importDialog);paintRows()}
function paintRows(){$('#rows').innerHTML=filtered().map((r,i)=>`<tr><td>${i+1}</td><td><b>${esc(r.data.name)}</b></td><td>${esc(r.data.detail)}</td><td>${esc(r.data.extra)}</td><td>${state.user.role==='teacher'&&!['attendance','grades'].includes(page)?'<span class="muted">Ko‘rish</span>':`<button class="textbutton edit" data-id="${r.id}">Tahrirlash</button><button class="danger remove" data-id="${r.id}">O‘chirish</button>`}</td></tr>`).join('');$('#empty').innerHTML=filtered().length?'':`<div class="empty"><span>${icon(page)}</span><h3>${query?'Natija topilmadi':'Hozircha ma’lumot yo‘q'}</h3><p>Yangi ma’lumot kiritish uchun “Qo‘shish” tugmasini bosing.</p></div>`;$('#rowcount').textContent=filtered().length+' ta yozuv';document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>recordDialog(records.find(r=>r.id===b.dataset.id)));document.querySelectorAll('.remove').forEach(b=>b.onclick=async()=>{if(!confirm('Ushbu yozuv o‘chirilsinmi?'))return;await mutation('records',{action:'delete',kind:page,id:b.dataset.id})})}
function dialog(html){$('#dialog').innerHTML=`<button id="close" class="close" aria-label="Yopish">×</button>${html}`;$('#dialog').showModal();$('#close').onclick=()=>$('#dialog').close()}
async function mutation(path,b){try{await api(path,b);$('#dialog').close();await load();notice('Saqlandi')}catch(e){notice(e.message,true)}}
function recordDialog(r){if(['students','schedule','attendance','grades','announcements'].includes(page)){schoolRecordDialog(r);return}dialog(`<h2>${r?'Yozuvni tahrirlash':'Yangi yozuv'}</h2><form id="recordform">${fields[page].map((f,i)=>`<label>${f}<input name="${['name','detail','extra'][i]}" ${i===0?'required':''} maxlength="250" value="${esc(r?.data[['name','detail','extra'][i]]||'')}"></label>`).join('')}<button class="primary">Saqlash</button></form>`);$('#recordform').onsubmit=e=>{e.preventDefault();mutation('records',{kind:page,id:r?.id,data:{...r?.data,...Object.fromEntries(new FormData(e.target))}})}}
function exportCSV(){const protect=v=>/^[=+@\-\t\r]/.test(v)?"'"+v:v;const csv='\uFEFF'+[fields[page],...filtered().map(r=>[r.data.name,r.data.detail,r.data.extra])].map(row=>row.map(v=>'"'+protect(String(v)).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=page+'.csv';a.click();URL.revokeObjectURL(url)}
function parseCSV(text){const rows=[];let row=[],field='',quoted=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if(c==='\n'&&!quoted){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row)}if(quoted)throw Error('CSV qo‘shtirnoqlarini tekshiring');return rows.filter(r=>r.some(v=>v.trim()))}
function importDialog(){dialog('<h2>CSV import</h2><p>CSV fayli 3 ustundan iborat bo‘lsin. Birinchi qator — ustun nomlari. Avval CSV yuklash orqali namunani oling. Bir martada 200 qatorgacha.</p><form id="importform"><label>CSV fayli<input type="file" name="file" accept=".csv,text/csv" required></label><div id="importstatus" role="status"></div><button class="primary">Tekshirish va import qilish</button></form>');$('#importform').onsubmit=async e=>{e.preventDefault();const file=e.target.file.files[0];if(file.size>200000){notice('Fayl hajmi 200 KB dan oshmasin',true);return}let rows;try{rows=parseCSV(await file.text()).slice(1);if(rows.length>200||!rows.length||rows.some(r=>r.length!==3||!r[0].trim()||r.some(v=>v.length>250)))throw Error('Har bir qatorda 3 ustun, nom esa to‘ldirilgan bo‘lishi kerak. Maksimum 200 qator.')}catch(e){notice(e.message,true);return}const button=e.target.querySelector('button');button.disabled=true;let done=0;try{for(const r of rows){await api('records',{kind:page,data:{name:r[0],detail:r[1],extra:r[2]}});done++;$('#importstatus').textContent=`${done} / ${rows.length} qator saqlandi`}$('#dialog').close();await load();notice(done+' qator import qilindi')}catch(e){notice(`${done} qator saqlandi. ${e.message} Qayta import takroriy yozuv yaratishi mumkin.`,true)}finally{button.disabled=false}}}
function access(){$('#page').innerHTML=`<section class="panel"><h3>O‘qituvchi va zavuchga foydalanish huquqi berish</h3><p class="muted">Taklif kodi 48 soat amal qiladi. Uni foydalanuvchiga o‘zingiz yetkazing. Har bir foydalanuvchi parolini o‘zi belgilaydi.</p><form id="memberform"><label>Hisob turi<select name="role" id="memberrole"><option value="teacher">O‘qituvchi — o‘z fanlari va guruhlari</option><option value="zavuch">O‘quv ishlari bo‘yicha direktor o‘rinbosari</option></select></label><div class="formgrid"><label>F.I.Sh.<input name="name" maxlength="150" required></label><label>Elektron pochta<input name="email" type="email" required></label></div><div class="checks">${[].map(k=>`<label><input type="checkbox" name="permissions" value="${k}" checked>${labels[k]}</label>`).join('')}</div><label class="reviewcheck" id="paymentcheck"><input type="checkbox" name="paymentApproved" required>Bir martalik 400 000 so‘m to‘lovni tekshirdim. Kirishga ruxsat beraman.</label><button class="primary">To‘lovni tasdiqlash va taklif kodi yaratish</button></form><div id="invitebox"></div><h3 class="mt">Foydalanuvchilar</h3>${members.length?members.map(m=>`<div class="role"><div><b>${esc(m.name)} · ${m.role==='teacher'?'O‘qituvchi':'O‘quv ishlari bo‘yicha o‘rinbosar'}</b><p>${esc(m.email)} · ${m.role==='zavuch'?(m.active?'Zavuch uchun bepul kirish':'Kirish bekor qilingan'):!m.payment_approved?'To‘lov tasdiqlanmagan — kirish yopiq':m.active?(m.activated?'To‘lov tasdiqlangan — kirish ochiq':'To‘lov tasdiqlangan — hisobni faollashtirish kerak'):'Kirish bekor qilingan'}</p><small>${m.permissions.map(k=>labels[k]).join(' · ')||'Bo‘limga ruxsat yo‘q'}</small></div><div class="memberbuttons">${m.role==='teacher'&&!m.payment_approved?`<button class="primary approvepayment" data-id="${m.id}">400 000 so‘m to‘landi — kirishga ruxsat</button>`:''}<button class="secondary permissions" data-id="${m.id}">Kirishni tiklash</button><button class="danger revoke" data-id="${m.id}">Bekor qilish</button></div></div>`).join(''):'<p class="empty">Hozircha qo‘shimcha foydalanuvchi yo‘q.</p>'}</section>`;$('#memberrole').onchange=()=>{const teacher=$('#memberrole').value==='teacher';$('#paymentcheck').innerHTML=teacher?'<input type="checkbox" name="paymentApproved" required>Bir martalik 400 000 so‘m to‘lovni tekshirdim. Kirishga ruxsat beraman.':'Zavuch uchun kirish bepul. To‘lov tasdiqlash talab qilinmaydi.';$('#memberform').querySelector('button').textContent=teacher?'To‘lovni tasdiqlash va taklif kodi yaratish':'Zavuchga bepul taklif kodi yaratish';};const syncPayment=()=>{const f=$('#memberform'),m=members.find(x=>x.email.toLowerCase()===f.elements.email.value.trim().toLowerCase());if($('#memberrole').value==='teacher'&&m?.payment_approved&&m.payment_amount===400000){$('#paymentcheck').innerHTML='Bir martalik 400 000 so‘m to‘lov avval tasdiqlangan. Qayta to‘lov talab qilinmaydi.';}else $('#memberrole').onchange();};$('#memberform').elements.email.addEventListener('input',syncPayment);$('#memberrole').addEventListener('change',syncPayment);$('#memberform').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target);busy=true;const button=e.target.querySelector('button');button.disabled=true;try{if(members.some(m=>m.email.toLowerCase()===String(f.get('email')).toLowerCase())&&!confirm('Bu email mavjud. Yangi taklif avvalgi parol va seanslarni bekor qiladi. Davom etilsinmi?'))return;const r=await api('members',{name:f.get('name'),email:f.get('email'),role:f.get('role'),paymentApproved:f.get('paymentApproved')==='on',permissions:f.getAll('permissions')});members=(await api('members')).members;access();$('#invitebox').innerHTML='<div class="invitation"><b>Bir martalik taklif kodi</b><p id="code"></p><small>Ushbu kod faqat hozir ko‘rsatiladi. Foydalanuvchi kirish oynasidagi “Taklif kodi bilan faollashtirish” tugmasidan foydalanadi.</small></div>';$('#code').textContent=r.invite}catch(e){notice(e.message,true)}finally{busy=false;button.disabled=false}};document.querySelectorAll('.approvepayment').forEach(b=>b.onclick=()=>{if(confirm('Bir martalik 400 000 so‘m to‘lovni tekshirdingizmi? Kirishga ruxsat berilsinmi?'))mutation('members',{action:'approve_payment',id:b.dataset.id})});document.querySelectorAll('.revoke').forEach(b=>b.onclick=()=>{if(confirm('Foydalanuvchining kirish huquqi bekor qilinsinmi? Avvalgi to‘lov tasdig‘i saqlanadi.'))mutation('members',{action:'revoke',id:b.dataset.id})});document.querySelectorAll('.permissions').forEach(b=>b.onclick=()=>{const m=members.find(m=>m.id===b.dataset.id);dialog(`<h2>Kirish huquqini tiklash</h2><p>${esc(m.name)}</p><p>Hisob faollashtiriladi. O‘qituvchining to‘lovi tasdiqlanmagan bo‘lsa, kirish yopiq qoladi. Zavuch uchun kirish bepul. Vakolatlar hisob turiga ko‘ra belgilanadi: zavuch — barcha o‘quv bo‘limlari, o‘qituvchi — o‘z fanlari, guruhlari va darsga tayyorgarligi.</p><form id="permissionsform"><div class="checks">${[].map(k=>`<label><input type="checkbox" name="permissions" value="${k}" ${m.permissions.includes(k)?'checked':''}>${labels[k]}</label>`).join('')}</div><button class="primary">Saqlash</button></form>`);$('#permissionsform').onsubmit=e=>{e.preventDefault();mutation('members',{action:'permissions',email:m.email,name:m.name,permissions:new FormData(e.target).getAll('permissions')})}})}
function audit(){$('#page').innerHTML=`<section class="panel"><h3>Oxirgi 100 ta amal</h3><div class="tablewrap"><table><thead><tr><th>Vaqt</th><th>Foydalanuvchi</th><th>Amal</th><th>Ma’lumot</th></tr></thead><tbody>${history.map(r=>`<tr><td>${esc(new Date(r.created_at).toLocaleString('uz-UZ',{timeZone:'Asia/Tashkent'}))}</td><td>${esc(r.name)}</td><td>${esc({login:'Kirish',setup:'Administrator yaratish',activate:'Faollashtirish',save:'Saqlash',delete:'O‘chirish',invite:'Taklif',revoke:'Huquqni bekor qilish',permissions:'Vakolatlarni o‘zgartirish'}[r.action]||r.action)}</td><td>${esc(r.detail)}</td></tr>`).join('')}</tbody></table></div></section>`}
load();


const planSections={aim:'Fanning maqsadi',tasks:'Fanning vazifalari',outcomes:'O‘lchanadigan ta’lim natijalari',independent:'Mustaqil ish mazmuni va topshiriqlari',resources:'Moddiy-texnik va o‘quv-uslubiy ta’minot',assessment:'Baholash tartibi va mezonlari',literature:'Asosiy, qo‘shimcha va elektron manbalar',digital:'Raqamli vositalar, akademik halollik va ma’lumotlarni himoya qilish talablari'};
function preparation(){const canCreate=state.user.role!=='admin';$('#page').innerHTML=`<section class="panel"><div class="toolbar"><div><h3>396-son buyruq asosida hujjatlar</h3><p class="muted">Namunaviy dastur → mavzular va soatlarni tekshirish → ishchi dastur, taqvim va har bir mavzu uchun dars hujjatlari</p></div>${canCreate?'<button class="primary" id="newprogram">+ Yangi dastur</button>':''}</div><p>2026-yil 17-sentabrdagi 396-son buyruqning 1-ilovasi va 2-ilovadagi 2-shakl asosida. Fayldan ajratilgan matn va mavzularni tekshirib, ishchi o‘quv rejadagi soatlarni kiriting.</p>${programs.length?programs.map(r=>`<div class="role"><div><b>${esc(r.data.subject)}</b><p>${esc(r.data.teacher)} · ${esc(r.data.course)}-kurs · ${esc(r.data.year)}</p><small>${r.data.topics.length} ta mavzu · ${r.data.reviewed?'Tekshirilgan':'Qoralama'}</small></div><div class="memberbuttons"><button class="primary openlessons" data-id="${r.id}">Mavzular bo‘yicha hujjatlar</button><button class="secondary openprogram" data-id="${r.id}">${canCreate?'Ochish / tahrirlash':'Ko‘rish'}</button><button class="secondary downloadprogram" data-id="${r.id}" data-format="program">Ishchi dastur Word</button><button class="secondary downloadprogram" data-id="${r.id}" data-format="calendar">Taqvim Word</button></div></div>`).join(''):'<div class="empty"><h3>Hozircha dastur tayyorlanmagan</h3><p>Nam‌unaviy dastur faylini yuklashdan boshlang.</p></div>'}</section>`;$('#newprogram')?.addEventListener('click',()=>programEditor());document.querySelectorAll('.openlessons').forEach(b=>b.onclick=()=>lessonList(b.dataset.id));document.querySelectorAll('.openprogram').forEach(b=>b.onclick=()=>programEditor(programs.find(r=>r.id===b.dataset.id)));document.querySelectorAll('.downloadprogram').forEach(b=>b.onclick=()=>downloadProgram(b.dataset.id,b.dataset.format))}
async function downloadProgram(id,format){try{let blob;if(demo)blob=await demo.download(id,format);else{const r=await fetch('/api/preparation/'+encodeURIComponent(id)+'/'+format);if(!r.ok){const d=await r.json();throw Error(d.error)}blob=await r.blob()}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(demo?'Namoyish_':'')+(format==='program'?'Ishchi_dastur':'Taqvim_reja')+'.docx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){notice(e.message,true)}}
function blankTopic(title=''){return {title,type:'Nazariy',hours:0,selfHours:0,content:'',homework:'',independentTask:'',reference:'',date:'',note:''}}
function programEditor(record){const viewOnly=state.user.role==='admin';let d=record?structuredClone(record.data):{subject:'',teacher:state.user.name,direction:'',course:'1',groups:'',year:'2026/2027',department:'',director:'',deputy:'',departmentHead:'',departmentDecision:'',councilDecision:'',sourceName:'',sourceId:'',plannedHours:'',reviewed:false,topics:[blankTopic()],...Object.fromEntries(Object.keys(planSections).map(k=>[k,'']))};let sourceText='';const metadata={subject:'Fan nomi',teacher:'Ishlab chiquvchi o‘qituvchi',direction:'Ta’lim yo‘nalishi',course:'Kurs',groups:'Guruhlar',year:'O‘quv yili',department:'Kafedra / metodik birlashma',plannedHours:'Ishchi o‘quv rejadagi auditoriya soati',sourceName:'Asos bo‘lgan namunaviy dastur rekvizitlari',director:'Direktor F.I.Sh.',deputy:'O‘quv ishlari bo‘yicha direktor o‘rinbosari F.I.Sh.',departmentHead:'Kafedra mudiri F.I.Sh.',departmentDecision:'Kafedra yig‘ilishi sanasi va raqami',councilDecision:'Pedagogik kengash sanasi va qarori'};
$('#page').innerHTML=`<section class="panel"><div class="toolbar"><h3>Dar‌sga tayyorgarlik — ishchi dastur va taqvim reja</h3><button type="button" id="backprograms" class="secondary">Ro‘yxatga qaytish</button></div><p class="note">Ishchi dastur: direktor — «Tasdiqlayman», o‘quv ishlari bo‘yicha direktor o‘rinbosari — «Ko‘rib chiqildi». Taqvim reja: faqat o‘quv ishlari bo‘yicha direktor o‘rinbosari — «Tasdiqlayman».</p><form id="programform"><fieldset ${viewOnly?'disabled':''}><h3>1. Namunaviy dasturni yuklash</h3><label>Matnli PDF yoki DOCX, 5 MB gacha<input type="file" id="programsource" accept=".pdf,.docx"></label><p id="sourcestatus">${d.sourceId?'Yuklangan manba saqlangan.':'Hali fayl yuklanmagan.'}</p><details><summary>Yuklangan matnni ko‘rish</summary><textarea id="sourcetext" rows="10" readonly></textarea></details><h3 class="mt">2. Umumiy ma’lumotlar</h3><div class="formgrid">${Object.entries(metadata).map(([k,v])=>`<label>${v}<input name="${k}" ${k==='plannedHours'?'type="number" min="0.5" step="0.5"':'type="text"'} maxlength="500" value="${esc(d[k]||'')}"></label>`).join('')}</div><label>Ishchi dastur muqovasining fan mavzusi<select id="covertheme">${Object.entries(coverThemes).map(([k,v])=>`<option value="${k}" ${(d.coverTheme||'auto')===k?'selected':''}>${v}</option>`).join('')}</select></label><p class="muted">Birinchi sahifa fan mavzusiga mos muqova bo‘ladi. Keyingi sahifada «TASDIQLAYMAN» va «KO‘RIB CHIQILDI» yonma-yon joylashadi.</p><h3 class="mt">3. Dastur bo‘limlari</h3><p class="muted">Mazmunni namunaviy dasturdan kelib chiqib kiriting. Tizim yetishmayotgan fan mazmunini to‘qib to‘ldirmaydi.</p>${Object.entries(planSections).map(([k,v])=>`<label>${v}<textarea name="${k}" rows="4" maxlength="12000">${esc(d[k]||'')}</textarea></label>`).join('')}<h3 class="mt">4. Mavzular va soatlar</h3><div class="toolbar"><button type="button" id="addtopic" class="secondary">+ Mavzu</button><button type="button" id="suggesttopics" class="secondary">Yuklangan fayldan mavzularni ajratish</button></div><p class="muted">Ajratilgan sarlavhalar taxminiy. Har bir mavzu, mazmun va soatni tekshiring. Nazorat mashg‘ulotlarini ishchi o‘quv reja talabiga ko‘ra alohida qator sifatida kiriting.</p><div id="topicseditor"></div><p id="plantotals" class="note"></p><label class="reviewcheck"><input type="checkbox" id="planreviewed" ${d.reviewed?'checked':''}>Nam‌unaviy dastur, mavzular va soatlarni tekshirdim. Auditoriya soatlari ishchi o‘quv rejaga mos.</label></fieldset>${!viewOnly?'<button type="submit" class="primary">Dasturni saqlash</button>':''}<p id="planerror" role="alert"></p></form></section>`;
$('#backprograms').onclick=()=>{if(viewOnly||confirm('Saqlanmagan o‘zgarishlar bekor qilinsinmi?'))preparation()};function collect(){d.coverTheme=$('#covertheme').value;for(const k of [...Object.keys(metadata),...Object.keys(planSections)])d[k]=$('#programform').elements[k].value;d.plannedHours=Number(d.plannedHours);d.reviewed=$('#planreviewed').checked}
function drawTopics(){$('#topicseditor').innerHTML=d.topics.map((r,i)=>`<details class="topiccard" ${i===0?'open':''}><summary>${i+1}. ${esc(r.title||'Yangi mavzu')}</summary><div class="formgrid"><label>Mavzu<input data-row="${i}" data-key="title" value="${esc(r.title)}" maxlength="500"></label><label>Mashg‘ulot turi<select data-row="${i}" data-key="type">${['Nazariy','Amaliy','Laboratoriya','Seminar'].map(t=>`<option ${r.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Auditoriya soati<input type="number" min="0.5" step="0.5" data-row="${i}" data-key="hours" value="${r.hours}"></label><label>Mustaqil ish soati<input type="number" min="0" step="0.5" data-row="${i}" data-key="selfHours" value="${r.selfHours}"></label><label>Sana<input type="date" data-row="${i}" data-key="date" value="${esc(r.date)}"></label><label>Manbalar<input data-row="${i}" data-key="reference" value="${esc(r.reference)}" maxlength="4000"></label></div>${[['content','Mavzuning mazmuni'],['homework','Uyga vazifa'],['independentTask','Mustaqil ish topshirig‘i'],['note','Izoh']].map(([k,v])=>`<label>${v}<textarea data-row="${i}" data-key="${k}" rows="3" maxlength="4000">${esc(r[k])}</textarea></label>`).join('')}<button type="button" class="danger removetopic" data-index="${i}">Mavzuni olib tashlash</button></details>`).join('');document.querySelectorAll('[data-row]').forEach(el=>el.oninput=()=>{d.topics[Number(el.dataset.row)][el.dataset.key]=['hours','selfHours'].includes(el.dataset.key)?Number(el.value):el.value;$('#planreviewed').checked=false;updateTotals()});document.querySelectorAll('.removetopic').forEach(b=>b.onclick=()=>{if(confirm('Mavzu olib tashlansinmi?')){d.topics.splice(Number(b.dataset.index),1);$('#planreviewed').checked=false;drawTopics()}});updateTotals()}
function updateTotals(){const a=d.topics.reduce((s,r)=>s+Number(r.hours||0),0),m=d.topics.reduce((s,r)=>s+Number(r.selfHours||0),0);$('#plantotals').textContent=`Auditoriya jami: ${a} soat · Mustaqil ish: ${m} soat · Umumiy yuklama: ${a+m} soat`}
drawTopics();$('#addtopic').onclick=()=>{d.topics.push(blankTopic());$('#planreviewed').checked=false;drawTopics()};$('#programsource').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){notice('Fayl 5 MB dan oshmasin',true);return}$('#sourcestatus').textContent='Fayl o‘qilmoqda…';try{const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});const r=await api('preparation/upload',{name:file.name,base64});d.sourceId=r.id;sourceText=r.text;for(const [key,value] of Object.entries(r.sections||{})){const el=$('#programform').elements[key];if(el&&!el.value.trim())el.value=value;}$('#sourcetext').value=r.text;$('#programform').elements.sourceName.value=r.name;$('#sourcestatus').textContent='Yuklandi: '+r.name;const extracted=r.topicDrafts||extractTopicDrafts(r.text);if(extracted.length&&d.topics.every(t=>!t.title.trim()&&!t.content.trim())){d.topics=extracted.map(t=>({...blankTopic(t.title),content:t.content.slice(0,4000)}));drawTopics();$('#sourcestatus').textContent+=' · '+extracted.length+' ta mavzu mazmuni bilan ajratildi. Soatlarni tekshirib saqlang.';}$('#planreviewed').checked=false}catch(e){$('#sourcestatus').textContent=e.message;notice(e.message,true)}};
$('#suggesttopics').onclick=()=>{if(!sourceText){notice('Avval namunaviy dasturni yuklang.',true);return}const topics=extractTopicDrafts(sourceText);if(!topics.length){notice('Mavzu sarlavhalari aniqlanmadi. Mavzularni qo‘lda kiriting.',true);return}if(confirm(topics.length+' ta mavzu mazmuni bilan topildi. Mavjud mavzular ro‘yxati almashtirilsinmi?')){d.topics=topics.map(t=>({...blankTopic(t.title),content:t.content.slice(0,4000)}));$('#planreviewed').checked=false;drawTopics()}};
$('#programform').oninput=e=>{if(e.target.id!=='planreviewed')$('#planreviewed').checked=false};$('#programform').onsubmit=async e=>{e.preventDefault();if(busy)return;collect();busy=true;const btn=e.target.querySelector('button[type="submit"]');btn.disabled=true;try{const saved=await api('preparation',{id:record?.id,data:d});record={id:saved.id,data:structuredClone(d)};await load();if(d.sourceId){try{await api('preparation/'+encodeURIComponent(saved.id)+'/lessons/generate',{});await lessonList(saved.id);notice('Dastur saqlandi. Har bir mavzu uchun uchta hujjat qoralamasi tayyor.')}catch(error){notice('Dastur saqlandi. Dars hujjatlari: '+error.message,true)}}else notice('Dastur saqlandi. Dars hujjatlari uchun namunaviy dasturni yuklang.')}catch(e){$('#planerror').textContent=e.message}finally{busy=false;btn.disabled=false}}}


async function technicalDashboard(){$('#page').innerHTML=`<section class="panel technicalintro"><span class="eyebrow">TEXNIK NAZORAT</span><h2>To‘lovlar va kirish boshqaruvi</h2><p>Bu kabinet to‘lovni tekshirib kirishga ruxsat berish, hisob ochish, kirishni bekor qilish va xizmat holatini kuzatish uchun. O‘qituvchi uchun bir martalik to‘lov — 400 000 so‘m. Oylik qayta to‘lov yo‘q. To‘lov va kirish ruxsatini faqat siz tasdiqlaysiz. Zavuch uchun kirish bepul. O‘quv ma’lumotlari zavuch kabinetida.</p><div class="demologin"><b>Kabinetlarni parolsiz sinab ko‘rish</b><p>Namoyish rejimi — namunaviy ma’lumotlar bilan.</p><div><a class="secondary" href="/?demo=zavuch">Zavuch kabineti ↗</a><a class="secondary" href="/?demo=teacher">O‘qituvchi kabineti ↗</a></div></div><button class="primary" id="technicalaccess">${icon('access')} Hisoblar va kirish ruxsati</button></section><div class="stats"><div class="stat"><span>Qo‘shimcha hisoblar</span><strong>${members.length}</strong><small>Foydalanuvchilar</small></div><div class="stat"><span>Faol hisoblar</span><strong>${members.filter(m=>m.active&&(m.role==='zavuch'||m.payment_approved)).length}</strong><small>Kirish huquqi berilgan</small></div><div class="stat"><span>Server</span><strong id="techservice">…</strong><small>Xizmat holati</small></div><div class="stat"><span>Ma’lumotlar bazasi</span><strong id="techdatabase">…</strong><small>Ulanish holati</small></div></div>`;$('#technicalaccess').onclick=()=>go('access');try{const status=await api('technical');if($('#techservice'))$('#techservice').textContent=status.service;if($('#techdatabase'))$('#techdatabase').textContent=status.database}catch(e){if($('#techservice'))$('#techservice').textContent='Tekshiring';notice(e.message,true)}}



