function groupName(id){return records.find(r=>r.kind==='groups'&&r.id===id)?.data.name||'Guruh o‘chirilgan'}
function teacherName(id){return teacherAccounts.find(t=>t.id===id)?.name||(id===state.user.id?state.user.name:'O‘qituvchi')}
function groupSelect(value='',optional=false){return `${optional?'<option value="">Barcha guruhlar</option>':'<option value="">Guruhni tanlang</option>'}${records.filter(r=>r.kind==='groups').map(r=>`<option value="${esc(r.id)}" ${r.id===value?'selected':''}>${esc(r.data.name)}</option>`).join('')}`}
function assignmentSelect(value=''){return '<option value="">Fan va guruhni tanlang</option>'+assignments.map(a=>`<option value="${esc(a.id)}" ${a.id===value?'selected':''}>${esc(a.subject)} · ${esc(groupName(a.groupId))}${state.user.role==='zavuch'?' · '+esc(teacherName(a.teacherId)):''}</option>`).join('')}
function schoolRecordDialog(r){
 const d=r?.data||{},kind=page,existing=assignments.find(a=>a.teacherId===d.teacherId&&a.groupId===d.groupId&&a.subject===d.subject);
 let fieldsHTML='';
 if(kind==='students')fieldsHTML=`<label>F.I.Sh.<input name="name" required maxlength="250" value="${esc(d.name)}"></label><label>Guruh<select name="groupId" required>${groupSelect(d.groupId||studentGroup(r,records))}</select></label><label>Telefon / izoh<input name="extra" maxlength="250" value="${esc(d.extra)}"></label>`;
 else if(kind==='announcements')fieldsHTML=`<label>Sarlavha<input name="name" required maxlength="250" value="${esc(d.name)}"></label><label>E’lon matni<textarea name="detail" required maxlength="250" rows="4">${esc(d.detail)}</textarea></label><label>Guruh<select name="groupId">${groupSelect(d.groupId,true)}</select></label><label>Sana<input name="extra" type="date" required value="${esc(d.extra||dateParts().date)}"></label>`;
 else{
  fieldsHTML=`<label>Fan, guruh va o‘qituvchi<select name="assignment" id="entryassignment" required>${assignmentSelect(existing?.id)}</select></label>`;
  if(kind==='schedule')fieldsHTML+=`<div class="formgrid"><label>Hafta kuni<select name="weekday">${['Dushanba','Seshanba','Chorshanba','Payshanba','Juma','Shanba'].map((v,i)=>`<option value="${i+1}" ${String(i+1)===d.weekday?'selected':''}>${v}</option>`).join('')}</select></label><label>Xona<input name="room" maxlength="100" value="${esc(d.room)}"></label><label>Boshlanish vaqti<input name="startTime" type="time" required value="${esc(d.startTime||'09:00')}"></label><label>Tugash vaqti<input name="endTime" type="time" required value="${esc(d.endTime||'10:20')}"></label></div>`;
  else fieldsHTML+=`<label>O‘quvchi<select name="studentId" id="entrystudent" required></select></label><div class="formgrid"><label>Sana<input name="date" type="date" required value="${esc(d.date||dateParts().date)}"></label>${kind==='attendance'?`<label>Davomat<select name="status">${['Keldi','Kelmadi','Sababli'].map(v=>`<option ${v===d.status?'selected':''}>${v}</option>`).join('')}</select></label>`:`<label>Baho<select name="value">${[5,4,3,2,1].map(v=>`<option ${String(v)===d.value?'selected':''}>${v}</option>`).join('')}</select></label>`}</div>`;
 }
 dialog(`<h2>${r?'Yozuvni tahrirlash':'Yangi yozuv'}</h2><form id="schoolrecordform">${fieldsHTML}<button type="submit" class="primary">Saqlash</button><p id="entryerror" role="alert"></p></form>`);
 const fillStudents=()=>{const a=assignments.find(a=>a.id===$('#entryassignment')?.value);if($('#entrystudent'))$('#entrystudent').innerHTML='<option value="">O‘quvchini tanlang</option>'+records.filter(r=>r.kind==='students'&&studentGroup(r,records)===a?.groupId).map(r=>`<option value="${esc(r.id)}" ${r.id===d.studentId?'selected':''}>${esc(r.data.name)}</option>`).join('');};
 $('#entryassignment')?.addEventListener('change',fillStudents);fillStudents();
 $('#schoolrecordform').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),data={name:'',detail:'',extra:'',...f};delete data.assignment;
 if(f.assignment){const a=assignments.find(a=>a.id===f.assignment);if(!a)return;Object.assign(data,{teacherId:a.teacherId,groupId:a.groupId,subject:a.subject});}
 await mutation('records',{kind,id:r?.id,data});};
}
