function teacherProfile(){
 const subjects=[...new Set(assignments.map(a=>a.subject))],groups=records.filter(r=>r.kind==='groups'),lessons=ownSchedule();
 $('#page').innerHTML=`<section class="panel"><h3>Mening kabinetim</h3><div class="profile-details"><div><small>F.I.Sh.</small><strong>${esc(state.user.name)}</strong></div><div><small>Elektron pochta</small><strong>${esc(state.user.email)}</strong></div><div><small>O‘qitadigan fanlarim</small><strong>${subjects.map(esc).join(' · ')||'Hali biriktirilmagan'}</strong></div><div><small>Dars beradigan guruhlarim</small><strong>${groups.map(g=>esc(g.data.name)).join(' · ')||'Hali biriktirilmagan'}</strong></div><div><small>Haftalik jadval</small><strong>${lessons.length} ta mashg‘ulot</strong></div><div><small>O‘quvchilarim</small><strong>${records.filter(r=>r.kind==='students').length} nafar</strong></div></div><div class="memberbuttons"><button class="primary" id="profileprep">Darsga tayyorgarlik</button><button class="secondary" id="profileschedule">Dars jadvalim</button><button class="secondary" id="profilegroups">Guruhlarim</button></div></section>`;
 $('#profileprep').onclick=()=>go('preparation');$('#profileschedule').onclick=()=>go('schedule');$('#profilegroups').onclick=()=>go('groups');
}

async function lessonList(id){
 const record=programs.find(r=>r.id===id);if(!record)return notice('Dastur topilmadi',true);
 try{const {lessons}=await api('preparation/'+encodeURIComponent(id)+'/lessons');
 $('#page').innerHTML=`<section class="panel"><div class="toolbar"><div><h3>${esc(record.data.subject)} — mavzular bo‘yicha hujjatlar</h3><p class="muted">Har bir mavzu uchun konspekt, texnologik xarita va dars ishlanmasi.</p></div><button class="secondary" id="lessonback">Dasturlar ro‘yxati</button></div><p class="note">Hujjatlar namunaviy dasturdagi mazmun va mavzu ma’lumotlaridan qoralama sifatida tuziladi. Faqat sarlavha yoki qisqa reja bo‘lsa, batafsil konspekt matnini qo‘shing. Davomiylik dastlab 80 daqiqa; uni darsingizga moslang.</p><button class="primary" id="preparelessons">Barcha mavzular hujjatlarini tayyorlash</button><p class="muted">Mavjud hujjatlar va kiritgan tuzatishlaringiz saqlanadi.</p><div class="lesson-list">${lessons.map(l=>`<article class="lesson-card"><div><span class="lesson-number">${l.index+1}</span><h3>${esc(l.title)}</h3><small class="${l.stale?'lesson-warning':''}">${l.stale?'Mavzu o‘zgargan — hujjatni moslashtiring':!l.data?'Hali tayyorlanmagan':l.data.reviewed?'O‘qituvchi tekshirgan':!l.data.notes?'Qoralama · konspekt matni kerak':'Qoralama · tekshirish kerak'}</small></div><div class="memberbuttons">${Object.entries(lessonFormats).map(([k,v])=>`<button class="secondary lesson-open" data-index="${l.index}" data-format="${k}" ${!l.data?'disabled':''}>${v}</button>`).join('')}<button class="secondary lesson-zip" data-index="${l.index}" ${!l.data||l.stale?'disabled':''}>3 ta hujjat · ZIP ↓</button></div></article>`).join('')}</div></section>`;
 $('#lessonback').onclick=preparation;$('#preparelessons').onclick=async e=>{e.target.disabled=true;try{await api('preparation/'+encodeURIComponent(id)+'/lessons/generate',{});await lessonList(id);notice('Mavzular uchun hujjatlar tayyorlandi. Mazmun va vaqtlarni tekshiring.')}catch(error){notice(error.message,true);e.target.disabled=false}};
 document.querySelectorAll('.lesson-open').forEach(b=>b.onclick=()=>lessonEditor(record,lessons.find(l=>l.index===Number(b.dataset.index)),b.dataset.format));
 document.querySelectorAll('.lesson-zip').forEach(b=>b.onclick=()=>downloadLesson(id,Number(b.dataset.index),'bundle',b));
 }catch(e){notice(e.message,true)}
}
async function downloadLesson(id,index,format,button){if(button)button.disabled=true;try{let blob;if(demo)blob=await demo.downloadLesson(id,index,format);else{const r=await fetch('/api/preparation/'+encodeURIComponent(id)+'/lessons/'+index+'/'+format);if(!r.ok){const d=await r.json();throw Error(d.error)}blob=await r.blob()}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(demo?'Namoyish_':'')+(index+1)+'_'+(lessonFormats[format]||'Dars_hujjatlari').replaceAll(' ','_')+(format==='bundle'?'.zip':'.docx');a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}catch(e){notice(e.message,true)}finally{if(button)button.disabled=false}}
function lessonEditor(record,entry,format='notes'){
 let d=structuredClone(entry.data),dirty=false;const title=record.data.topics[entry.index].title;
 function draw(){const fields=format==='notes'?['objectives','outline','terms','notes','questions','practice','homework','resources']:format==='map'?['objectives','methods','assessment','homework']:['objectives','methods','resources','outline','notes','practice','questions','assessment','summary','homework'];
 $('#page').innerHTML=`<section class="panel lesson-editor"><div class="toolbar"><div><h3>${entry.index+1}. ${esc(title)}</h3><p class="muted">${esc(record.data.subject)} · ${esc(record.data.teacher)}</p></div><button class="secondary" id="lessonlistback">Mavzular ro‘yxati</button></div>${entry.stale?'<p class="note lesson-warning">Dastur mavzusi yoki mazmuni o‘zgargan. Hujjat matnini yangi mavzuga moslab saqlang yoki qayta tayyorlang.</p>':''}<div class="lesson-tabs" role="group" aria-label="Hujjat turi">${Object.entries(lessonFormats).map(([k,v])=>`<button type="button" class="${k===format?'primary':'secondary'}" data-lessontab="${k}" aria-pressed="${k===format}">${v}</button>`).join('')}</div><form id="lessonform"><h3>${lessonFormats[format]}</h3><p class="muted">Uchala hujjat umumiy dars ma’lumotlaridan foydalanadi. Bir bo‘limdagi tuzatish tegishli hujjatlarda ham aks etadi.</p><label>Dars davomiyligi (daqiqa)<input id="lessonminutes" type="number" min="20" max="240" step="1" value="${d.minutes}" required></label><p class="muted">Davomiylik o‘zgarsa, bosqichlar vaqti mutanosib taqsimlanadi. Ularni alohida ham tahrirlashingiz mumkin.</p>${fields.map(k=>`<label>${lessonFields[k]}<textarea name="${k}" rows="${k==='notes'?12:4}" maxlength="${k==='notes'?20000:6000}" placeholder="${k==='notes'?'Dasturda batafsil matn bo‘lmasa, mavzu bo‘yicha nazariy mazmunni kiriting.':''}">${esc(d[k])}</textarea></label>`).join('')}${format!=='notes'?`<h3>Dars bosqichlari</h3><div class="lesson-stages">${d.stages.map((s,i)=>`<details class="topiccard" ${i===0?'open':''}><summary>${i+1}. ${esc(s.title)} · ${s.minutes} daqiqa</summary><div class="formgrid"><label>Bosqich nomi<input data-stage="${i}" data-stagekey="title" value="${esc(s.title)}" maxlength="2000" required></label><label>Vaqt (daqiqa)<input data-stage="${i}" data-stagekey="minutes" type="number" min="0" max="240" step="1" value="${s.minutes}" required></label></div>${[['teacher','O‘qituvchi faoliyati'],['student','O‘quvchi faoliyati'],['method','Metod'],['assessment','Baholash']].map(([k,v])=>`<label>${v}<textarea data-stage="${i}" data-stagekey="${k}" maxlength="2000" rows="3" required>${esc(s[k])}</textarea></label>`).join('')}</details>`).join('')}</div><p class="note" id="lessonminutesum">Bosqichlar jami: ${d.stages.reduce((n,s)=>n+s.minutes,0)} daqiqa</p>`:''}<label class="reviewcheck"><input type="checkbox" id="lessonreviewed" ${d.reviewed?'checked':''}>Mazmun, topshiriqlar va vaqt taqsimotini tekshirdim.</label><p class="muted">Tekshirilmagan Word hujjatlarida «Qoralama» belgisi bo‘ladi.</p><p id="lessonerror" role="alert"></p><div class="lesson-actions"><button class="primary" type="submit">Saqlash</button><button class="secondary" type="button" id="lessonword">Saqlash va Word ↓</button><button class="secondary" type="button" id="lessonbundle">Saqlash va 3 ta hujjat ZIP ↓</button><button class="secondary" type="button" id="lessonregenerate">Mavzudan qayta tayyorlash</button></div></form></section>`;
 const form=$('#lessonform');function collect(){for(const k of fields)d[k]=form.elements[k].value;d.minutes=Number($('#lessonminutes').value);d.reviewed=$('#lessonreviewed').checked;document.querySelectorAll('[data-stage]').forEach(el=>{d.stages[Number(el.dataset.stage)][el.dataset.stagekey]=el.dataset.stagekey==='minutes'?Number(el.value):el.value})}
 form.oninput=e=>{dirty=true;if(e.target.id!=='lessonreviewed')$('#lessonreviewed').checked=false;};
 $('#lessonminutes').onchange=()=>{collect();if(!Number.isInteger(d.minutes)||d.minutes<20||d.minutes>240)return;const times=allocateMinutes(d.minutes,d.stages.map(s=>s.minutes||1));d.stages.forEach((s,i)=>s.minutes=times[i]);d.reviewed=false;dirty=true;draw()};
 document.querySelectorAll('[data-stagekey="minutes"]').forEach(el=>el.addEventListener('input',()=>{collect();$('#lessonminutesum').textContent='Bosqichlar jami: '+d.stages.reduce((n,s)=>n+s.minutes,0)+' / '+d.minutes+' daqiqa'}));
 document.querySelectorAll('[data-lessontab]').forEach(b=>b.onclick=()=>{collect();format=b.dataset.lessontab;draw()});
 $('#lessonlistback').onclick=()=>{if(!dirty||confirm('Saqlanmagan o‘zgarishlar bekor qilinsinmi?'))lessonList(record.id)};
 let saving=false;async function saveDoc(exportFormat){if(saving)return;collect();const errors=validateLesson(d);if(errors.length){$('#lessonerror').textContent=errors.join('; ');return}saving=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{await api('preparation/'+encodeURIComponent(record.id)+'/lessons/'+entry.index,{hash:entry.hash,data:d});dirty=false;entry.stale=false;notice('Dars hujjatlari saqlandi.');if(exportFormat)await downloadLesson(record.id,entry.index,exportFormat);draw()}catch(e){$('#lessonerror').textContent=e.message}finally{saving=false;form.querySelectorAll('button').forEach(b=>b.disabled=false)}}
 form.onsubmit=e=>{e.preventDefault();saveDoc()};$('#lessonword').onclick=()=>saveDoc(format);$('#lessonbundle').onclick=()=>saveDoc('bundle');
 $('#lessonregenerate').onclick=async e=>{if(!confirm('Ushbu mavzuga kiritgan tuzatishlaringiz o‘rniga dasturdan yangi qoralama tayyorlansinmi?'))return;e.target.disabled=true;try{await api('preparation/'+encodeURIComponent(record.id)+'/lessons/generate',{replaceIndex:entry.index});await lessonList(record.id);notice('Mavzu hujjatlari qayta tayyorlandi.')}catch(error){notice(error.message,true);e.target.disabled=false}};
 }draw();
}
